        {
          "text": "AI has become a mainstream skill requirement, making JS/Python job search harder without it.",
          "evidence": [8]
        },
        {
          "text": "P1 expects the recruiter profession to disappear in the future.",
          "evidence": [14]
        }
      ]
    },
    {
      "id": "ai-development-acceleration",
      "title": "AI impact on development speed and code quality",
      "claims": [
        {
          "text": "Development speed accelerated sharply after 2025; tools are now good but increasingly expensive.",
          "evidence": [9]
        },
        {
          "text": "Using GPT to generate SQL joins and other code reduces routine work and speeds development.",
          "evidence": [19]
        },
        {
          "text": "AI‑generated code can produce overly large, inefficient queries that raise security and performance concerns.",
          "evidence": [30]
        },
        {
          "text": "A team dropped AI‑generated feature code because it lacked adequate quality.",
          "evidence": [35]
        },
        {
          "text": "Incremental computations were replaced with a database view, signifying a technical shift.",
          "evidence": [34]
        }
      ]
    },
    {
      "id": "architecture-decisions",
      "title": "Technical and architectural choices",
      "claims": [],
      "decisions": []
    },
    {
      "id": "candidate-search-quality",
      "title": "Quality of keyword‑based candidate search",
      "claims": [
        {
          "text": "Keyword‑based candidate search is more detached from reality than before.",
          "evidence": [13]
        }
      ]
    },
    {
      "id": "model-context-limitations",
      "title": "Limitations of simple AI models",
      "claims": [
        {
          "text": "Higher‑quality AI responses require a well‑configured environment and accumulated context; simple models cannot see this.",
          "evidence": [22]
        }
      ]
    }
  ],
  "decisions": [
    {
      "text": "The project will not use cloud services now or in the future.",
      "evidence": [19]
    },
    {
      "text": "The team decided to drop the AI‑generated code feature because it was inadequate.",
      "evidence": [35]
    }
  ],
  "openQuestions": [
    {
      "text": "Should logs be exported to JUnit for earlier detection of recurring issues?",
